const $=s=>document.querySelector(s),frame=$('#site');let content=[],entries=[],rules=[],activeId='overview',focusMode=true;
const components=[['Brand symbol','.brand-mark'],['Brand words','.brand-name'],['Header','.masthead,.case-brand'],['Intro group','.hero-copy,.case-intro'],['Greeting','.greeting'],['Headline','.headline-top,.case-intro h1'],['Connection headline','.headline-bottom'],['Role line','.hero-copy>p'],['Player scene','.scene-slot'],['Player deck','.independent-deck'],['LED housing','.scene-readout>.now-playing-led'],['LED text','.scene-readout strong'],['Previous track','button[aria-label="Previous track"]'],['Next track','button[aria-label="Next track"]'],['Menu island','.rail.balanced-menu'],['Menu object','.rail .menu-object'],['Menu label','.menu-label'],['Settings group','.local-time'],['Timezone selector','.city-select'],['Theme toggle','.ambient-toggle'],['Mobile menu button','.mobile-menu-toggle'],['Mobile dialog','.mobile-menu-dialog'],['Collection grid','#work .cabinet-shelf'],['Collection card','#work .cabinet-record'],['Record artwork','#work .jacket-art'],['Case name','.collection-summary>strong'],['Collection chip','.collection-chips>span'],['Page heading','.section h2'],['Section sidebar','.section-menu,body>aside'],['Case intro chips','.chips span'],['Case sleeve hero','.case-opening'],['Case section label','.section-label'],['Case section heading','.story-section h2'],['Case paragraph','.story-section>p:not(.section-label)'],['Case facts','.project-facts'],['Case figure','figure img'],['About text','#about p'],['Contact form','.contact-form'],['Form label','.contact-form label'],['Form input','.contact-form input'],['Form message','.contact-form textarea'],['Form action','.form-actions button'],['Footer','footer,.footer']];
const pageFor={collection:'../index.html#work','case-studies':'../case-studies/capi.html',forms:'../index.html#contact'};
const componentFor={identity:'Brand symbol',type:'Headline',color:'LED text',layout:'Player scene',player:'LED housing',navigation:'Menu island',collection:'Collection card','case-studies':'Case section label',forms:'Form input'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Math.round(n*100)/100;
function visual(id){if(id==='identity'||id==='overview')return '<img src="../assets/brand-record.svg" alt="Approved soft record symbol"><span class="wordmark">yeung designs</span>';if(id==='type')return '<span class="type-demo">meaningful connection</span>';if(id==='color')return [['#f7f4eb','Paper'],['#25332f','Ink'],['#bf4d3c','Heart'],['#0b2118','Glass'],['#b4ffbd','LED']].map(([c,n])=>`<div class="swatch"><i style="background:${c}"></i>${n}<br>${c}</div>`).join('');if(id==='player')return '<span class="round">◀</span><span class="mini-led">load record ▶</span><span class="round">▶</span>';if(id==='collection')return '<span class="chip">Product Design</span><span class="chip">Community Engagement</span><span class="chip">Mobile</span>';if(id==='layout')return '<div class="rhythm"><b>01 · Introduction</b><span>6% of fitted scene width</span><b>02 · Record player</b><span>6% of fitted scene width</span><b>03 · Navigation</b></div>';return '';}
function render(){const id=location.hash.slice(1);if(id==='inspector')return;const item=content.find(x=>x[0]===id)||content[0];activeId=item[0];window.scrollTo({top:0,behavior:'instant'});$('#article').innerHTML=`<p class="eyebrow">${esc(item[1].toUpperCase())}</p><h1>${esc(item[0]==='overview'?'Portfolio design system':item[1])}</h1><p class="lead">${esc(item[3].split('. ')[0]+(item[3].includes('. ')?'.':''))}</p>${visual(item[0])?`<div class="visual" aria-label="Illustrative component sample">${visual(item[0])}</div>`:''}<div class="cards">${item[4].map(([title,text])=>`<div class="card"><h3>${esc(title)}</h3><p>${esc(text.split(". ")[0])}${text.includes(". ")?".":""}</p>${text.includes(". ")?`<details><summary>Details</summary><p>${esc(text.split(". ").slice(1).join(". "))}</p></details>`:""}</div>`).join('')}</div>`;document.querySelectorAll('#navigation a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash==='#'+activeId)a.setAttribute('aria-current','page')});const page=pageFor[activeId]||'../index.html#home';if($('#page').value!==page){$('#page').value=page;loadPage()}else{measure();const selected=components.find(([n])=>n===componentFor[activeId]);if(selected&&[...$('#component').options].some(o=>o.value===selected[1])){$('#component').value=selected[1];showComponent()}}}
fetch('content.json').then(r=>r.json()).then(data=>{content=data;$('#navigation').innerHTML=data.map(s=>`<a href="#${s[0]}">${esc(s[1])}</a>`).join('');render()});window.addEventListener('hashchange',render);
$('#search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();for(const a of document.querySelectorAll('#navigation a')){const s=content.find(s=>'#'+s[0]===a.hash);a.hidden=!JSON.stringify(s).toLowerCase().includes(q)}});
function sizeFrame(){const [w,h]=$('#viewport').value.split(',').map(Number);frame.style.width=w+'px';frame.style.height=h+'px';const scale=Math.min(1,$('#canvas').clientWidth/w);frame.style.transform=`scale(${scale})`;$('#canvas').style.height=h*scale+'px';$('#canvas-label').textContent=`${w} × ${h} CSS px · shown at ${Math.round(scale*100)}%`;setTimeout(measure,350)}
function loadPage(){frame.src=$('#page').value}
$('#page').addEventListener('change',loadPage);$('#viewport').addEventListener('change',sizeFrame);$('#refresh').addEventListener('click',measure);$('#component').addEventListener('change',()=>{focusMode=true;showComponent()});$('#filter').addEventListener('input',showInventory);let canvasWidth=0;new ResizeObserver(()=>{const width=$('#canvas').clientWidth;if(width!==canvasWidth){canvasWidth=width;sizeFrame()}}).observe($('#canvas'));
frame.addEventListener('load',()=>{sizeFrame();const doc=frame.contentDocument;doc.fonts.ready.then(()=>setTimeout(measure,500));frame.contentWindow.addEventListener('hashchange',()=>setTimeout(measure,200));doc.addEventListener('click',()=>setTimeout(measure,200));});
function visible(e){const r=e.getBoundingClientRect(),s=frame.contentWindow.getComputedStyle(e);return r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'&&!e.closest('[hidden]')}
function cssRules(){let all=[];function walk(list,source,condition='all'){for(const r of list){if(r.selectorText)all.push({selector:r.selectorText,style:r.style,source,condition});else if(r.cssRules)walk(r.cssRules,source,r.conditionText||condition)}}for(const sheet of frame.contentDocument.styleSheets){try{walk(sheet.cssRules,(sheet.href||'inline').split('/').pop())}catch{}}return all}
function measure(){try{const doc=frame.contentDocument;if(!doc?.body)return;const prior=$('#component').value;const found=components.filter(([name,sel])=>[...doc.querySelectorAll(sel)].some(visible));$('#component').innerHTML=found.map(([n,s])=>`<option value="${esc(s)}">${esc(n)}</option>`).join('');const desired=found.find(([n])=>n===componentFor[activeId]);if(found.some(([,s])=>s===prior))$('#component').value=prior;else if(desired)$('#component').value=desired[1];rules=cssRules();entries=[...doc.querySelectorAll('body *')].filter(e=>visible(e)&&!['SCRIPT','STYLE','OPTION','SVG','PATH'].includes(e.tagName)&&([...e.childNodes].some(n=>n.nodeType===3&&n.textContent.trim())||e.matches('button,input,select,textarea,[role="switch"]'))).map(e=>{const r=e.getBoundingClientRect(),s=frame.contentWindow.getComputedStyle(e),target=e.matches('button,input,select,textarea,a,[role="switch"]');return{label:(e.getAttribute('aria-label')||e.textContent.trim()||e.getAttribute('name')||e.tagName).replace(/\s+/g,' ').slice(0,110),selector:e.tagName.toLowerCase()+(e.id?'#'+e.id:e.classList.length?'.'+[...e.classList].slice(0,2).join('.') :''),size:`${num(r.width)} × ${num(r.height)}`,font:`${s.fontSize} / ${s.lineHeight}; ${s.fontWeight}; ${s.fontFamily}`,spacing:`${s.padding} / ${s.margin}`,flags:[parseFloat(s.fontSize)<16?'Text below 16px':null,target&&(r.width<44||r.height<44)?'Review target below 44px':null].filter(Boolean).join('; ')}});showComponent();showInventory();$('#bounds').innerHTML=rules.flatMap(r=>[...r.style].filter(p=>/^(min|max)-|font-size|padding|margin|gap|radius|width|height/.test(p)&&/clamp\(|min\(|max\(|min-|max-/.test(p+' '+r.style.getPropertyValue(p))).map(p=>`<tr><td>${esc(r.source)}<small>${esc(r.condition)}</small></td><td>${esc(r.selector)}</td><td>${esc(p)}: ${esc(r.style.getPropertyValue(p))}</td></tr>`)).join('');}catch(error){$('#metrics').textContent='Preview unavailable. Open this guide from the same local server as the portfolio.'}}
$('#view-mode').addEventListener('click',()=>{focusMode=!focusMode;showComponent()});
function focusVisual(e){const [w,h]=$('#viewport').value.split(',').map(Number),canvas=$('#canvas');$('#view-mode').textContent=focusMode?'Full page':'Focus component';$('#view-mode').setAttribute('aria-pressed',String(focusMode));if(!focusMode){frame.style.clipPath='none';const scale=Math.min(1,canvas.clientWidth/w);frame.style.transform=`scale(${scale})`;canvas.style.height=h*scale+'px';$('#canvas-label').textContent=`${w} × ${h} CSS px · full page`;return;}const before=e.getBoundingClientRect();frame.contentWindow.scrollTo({top:Math.max(0,frame.contentWindow.scrollY+before.top-(h-before.height)/2),behavior:'instant'});const r=e.getBoundingClientRect();frame.style.clipPath=`inset(${Math.max(0,r.top-12)}px ${Math.max(0,w-r.right-12)}px ${Math.max(0,h-r.bottom-12)}px ${Math.max(0,r.left-12)}px)`;const scale=Math.min(3,(canvas.clientWidth-48)/Math.max(r.width,1),380/Math.max(r.height,1));const boxHeight=Math.max(180,Math.min(460,r.height*scale+64));canvas.style.height=boxHeight+'px';frame.style.transform=`translate(${(canvas.clientWidth-r.width*scale)/2-r.left*scale}px,${(boxHeight-r.height*scale)/2-r.top*scale}px) scale(${scale})`;$('#canvas-label').textContent=`${$('#component').selectedOptions[0]?.textContent} · ${Math.round(scale*100)}% inspection view`; }
function showComponent(){const sel=$('#component').value;if(!sel)return;const e=[...frame.contentDocument.querySelectorAll(sel)].find(visible);if(!e)return;focusVisual(e);const s=frame.contentWindow.getComputedStyle(e),r=e.getBoundingClientRect(),p=e.parentElement.getBoundingClientRect();const data=[['Rendered box',`${num(r.width)} × ${num(r.height)} px`],['Of parent width',`${num(r.width/p.width*100)}%`],['Computed font',`${s.fontSize} / ${s.lineHeight}`],['Font family',e.matches('.brand-mark')?'SVG artwork; inherited font not used':s.fontFamily],['Weight / tracking',`${s.fontWeight} / ${s.letterSpacing}`],['Padding',s.padding],['Margin',s.margin],['Gap',s.gap],['Radius',s.borderRadius],['Border',s.border],['Foreground',s.color],['Background',s.backgroundColor],['Min / max width',`${s.minWidth} / ${s.maxWidth}`],['Min / max height',`${s.minHeight} / ${s.maxHeight}`],['Home composition zoom',frame.contentWindow.getComputedStyle(frame.contentDocument.body).zoom]];$('#metrics').innerHTML='<dl>'+data.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')+'</dl>';const matched=rules.filter(r=>{try{return e.matches(r.selector)}catch{return false}});$('#rules').innerHTML=matched.map(r=>`<div class="rule"><b>${esc(r.source)}</b><br>${esc(r.condition)}<br><code>${esc(r.selector)} { ${esc(r.style.cssText)} }</code></div>`).join('')||'<p>No direct stylesheet rule. Some values may be inherited.</p>';}
function showInventory(){const q=$('#filter').value.toLowerCase(),shown=entries.filter(e=>(e.label+' '+e.selector).toLowerCase().includes(q));$('#count').textContent=`· ${entries.length} elements`;$('#inventory').innerHTML=shown.map(e=>`<tr><td>${esc(e.label)}<small>${esc(e.selector)}</small></td><td>${esc(e.size)}</td><td>${esc(e.font)}</td><td>${esc(e.spacing)}</td><td class="flag">${esc(e.flags)||'—'}</td></tr>`).join('')}
